def transform(grid):
    n = len(grid)
    out = [row[:] for row in grid]
    maps = (
        lambda r, c: (r, n - 1 - c),
        lambda r, c: (n - 1 - r, c),
        lambda r, c: (n - 1 - r, n - 1 - c),
        lambda r, c: (c, r),
        lambda r, c: (n - 1 - c, n - 1 - r),
        lambda r, c: (c, n - 1 - r),
        lambda r, c: (n - 1 - c, r),
    )
    for r in range(len(grid)):
        for c in range(n):
            if grid[r][c] == 2:
                for mapping in maps:
                    rr, cc = mapping(r, c)
                    if grid[rr][cc] != 2:
                        out[r][c] = grid[rr][cc]
                        break
    return out
